import pyAether as pyScript
def use_MdePlatSession_close():
    def close_session(libName, cellName, viewName):
        mde = pyScript.MdePlatSession.open(libName, cellName, viewName)
        if mde is None:
            error = pyScript.MdePlatSession.staticLastError()
            print(f"Failed to open session: {error}")
            return
        try:
            if not mde.isValid():
                print("Session is not valid")
                return
            if mde.close():
                print("Session closed successfully")
            else:
                error = mde.getLastError()
                print(f"Failed to close session: {error}")
        finally:
            if mde.isValid():
                mde.close()
    if __name__ == "__main__":
        close_session("testLib", "testCell", "testView")

