import pyAether as pyScript
def use_MdePlatSession_isValid():
    # Open a session
    mde = pyScript.MdePlatSession.open("testLib", "testCell", "platform")
    if mde:
        # Check if the session is valid
        if mde.isValid():
            print("Session is valid")
            # Perform operations...
            mde.close()
            # After closing, check validity again
            if not mde.isValid():
                print("Session is now invalid")
        else:
            print("Session is invalid")
    else:
        print("Session creation failed")

